**Step 2: Add AJAX polling JavaScript**

Replace the existing `<script>` section (lines 247-278) with:

```javascript
<script>
    (function() {
        var themeSwitch = document.getElementById('theme-switch');
        var storedTheme = localStorage.getItem('keepr-theme');
        var systemDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        var isDark = storedTheme === 'dark' || (!storedTheme && systemDark);

        themeSwitch.checked = isDark;

        themeSwitch.addEventListener('change', function() {
            if (this.checked) {
                document.documentElement.setAttribute('data-theme', 'dark');
                localStorage.setItem('keepr-theme', 'dark');
            } else {
                document.documentElement.removeAttribute('data-theme');
                localStorage.setItem('keepr-theme', 'light');
            }
        });

        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function(e) {
            if (!localStorage.getItem('keepr-theme')) {
                if (e.matches) {
                    document.documentElement.setAttribute('data-theme', 'dark');
                    themeSwitch.checked = true;
                } else {
                    document.documentElement.removeAttribute('data-theme');
                    themeSwitch.checked = false;
                }
            }
        });

        // AJAX polling for dashboard updates
        function updateDashboard() {
            fetch('/api/dashboard')
                .then(function(response) {
                    if (!response.ok) throw new Error('Network error');
                    return response.json();
                })
                .then(function(data) {
                    updateTable(data.servers);
                    updateCards(data.servers);
                })
                .catch(function(err) {
                    console.error('Dashboard update failed:', err);
                });
        }

        function updateTable(servers) {
            var tbody = document.querySelector('.server-table tbody');
            if (!tbody) return;

            servers.forEach(function(server, index) {
                var row = tbody.children[index];
                if (!row) return;

                var cells = row.querySelectorAll('td');
                // Update status (cell 1)
                cells[1].innerHTML = '<span class="status-dot status-' + server.status + '"></span>' + server.status;
                // Update last run (cell 2)
                cells[2].textContent = server.last_run;
                // Update next run (cell 3)
                cells[3].textContent = server.next_run;
            });
        }

        function updateCards(servers) {
            var cards = document.querySelectorAll('.server-card');

            servers.forEach(function(server, index) {
                var card = cards[index];
                if (!card) return;

                // Update status dot
                var statusDot = card.querySelector('.status-dot');
                statusDot.className = 'status-dot status-' + server.status;

                // Update info spans
                var infoSpans = card.querySelectorAll('.info span:not(.label)');
                infoSpans[0].textContent = server.status;
                infoSpans[1].textContent = server.last_run;
                infoSpans[2].textContent = server.next_run;
            });
        }

        // Poll every 5 seconds
        setInterval(updateDashboard, 5000);
    })();
</script>
```

